documents.capture:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {V: int}}}
output: {path: result.csv, columns: [ID, VALUE]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}

documents.checked:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {V: int}}}
output: {path: result.csv, columns: [ID, VALUE]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - name: VALUE
    type: int
    verifications:
      - allowed_values: {values: [0, 1.0]}
      - range: {min: 0.0, max: 1.5}

documents.correlated:
yamaa: "1.0"
type: spec
domain: TEST
base: SRC
keys: [ID, SEQ]
input:
  SRC: {path: src.csv, types: {ID: int, SEQ: int, CUT: int}}
  D: {path: donor.csv, types: {ID: int, TIME: int}}
output: {path: result.csv, columns: [ID, SEQ, A, B]}
intermediates:
  - id: P
    dataset: D
    key: [ID]
    filter: "D.TIME < SRC.CUT"
    order_by: [D.TIME]
    keep: last
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: SEQ, type: int, derivation: SRC.SEQ}
  - {name: A, type: str, derivation: P.A}
  - {name: B, type: str, derivation: P.B}

documents.single_key:
yamaa: "1.0"
type: spec
domain: TEST
base: SRC
keys: [ID]
input:
  SRC: {path: src.csv, types: {ID: int}}
  D: {path: donor.csv, types: {ID: int, SEQ: int}}
output: {path: result.csv, columns: [ID, A, B]}
intermediates:
  - id: P
    dataset: D
    key: [ID]
    order_by: [D.SEQ]
    keep: first
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: A, type: str, derivation: P.V}
  - {name: B, type: str, derivation: P.V}

documents.dependency_before_bad_filter:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID]
input:
  SRC: {path: src.csv, types: {N: int}}
  TAB: {path: tab.csv, types: {KINT: int, KNUM: float}}
base: SRC
output: {path: out.csv, columns: [ID, V, V2]}
intermediates:
  - id: LOOK
    dataset: TAB
    key: {K: {str_pad: {source: SRC.N, width: 8}}}
    filter: "TAB.KINT > 'bad'"
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: V, type: str, derivation: LOOK.VAL}
  - {name: V2, type: str, derivation: LOOK.VAL}

documents.range:
yamaa: "1.0"
type: spec
domain: TEST
base: SRC
keys: [ID, SEQ]
input:
  SRC: {path: src.csv, types: {ID: int, SEQ: int, X: int}}
  D: {path: donor.csv, types: {ID: int, LOW: int, HIGH: int, ORD: int}}
output: {path: result.csv, columns: [ID, SEQ, X, A, B]}
intermediates:
  - id: P
    dataset: D
    key: [ID]
    filter: "D.ELIG = 'Y'"
    between: {value: X, lower: LOW, upper: HIGH}
    columns: [V, W, V]
    order_by: [D.ORD]
    keep: first
    absent: absent
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: SEQ, type: int, derivation: SRC.SEQ}
  - {name: X, type: int, derivation: SRC.X}
  - {name: A, type: str, derivation: P.V}
  - {name: B, type: str, derivation: P.W}

documents.baseline:
yamaa: "1.0"
type: spec
domain: TEST
base: SRC
keys: [ID]
input:
  SRC: {path: src.csv, types: {TRTSDT: date}}
  VS: {path: donor.csv, types: {WEIGHT: float}}
output: {path: result.csv, columns: [ID, TRTSDT, WEIGHTBL]}
intermediates:
  - id: BL
    dataset: VS
    key: [ID]
    derivations:
      ADT: {to_date: {source: VSDTC}}
    between: {value: TRTSDT, lower: ADT}
    order_by: [VS.ADT]
    keep: last
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: TRTSDT, type: date, derivation: SRC.TRTSDT}
  - {name: WEIGHTBL, type: float, derivation: BL.WEIGHT}

documents.root_filter:
