documents.primary:
yamaa: "1.0"
type: spec
domain: TEST
base: SRC
keys: [ID, SEQ]
input:
  SRC: {path: src.csv, types: {ID: int, SEQ: int}}
output: {path: result.csv, columns: [ID, SEQ, A, B]}
intermediates:
  - id: P
    dataset: SRC
    key: [ID]
    filter: "SRC.ELIG = 'Y'"
    order_by: [SRC.SEQ]
    keep: last
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: SEQ, type: int, derivation: SRC.SEQ}
  - {name: A, type: str, derivation: P.A}
  - {name: B, type: str, derivation: P.B}

edits.to:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: VALUE, type: str, derivation: {case: [{when: 'SRC.V > 0', then: {str_extract: {source: SRC.TEXT, pattern: 'prefix:([A-Z]+)$', group: 1}}}, {otherwise: "'none'"}]}}
rows: [{id: records, dataset: SRC}]

  - {name: ID, type: str, derivation: SRC.ID}
  - {name: VALUE, type: str}
rows: [{id: records, dataset: SRC, derivations: {VALUE: {case: [{when: 'SRC.V > 0', then: {str_extract: {source: SRC.TEXT, pattern: 'prefix:([A-Z]+)$', group: 1}}}, {otherwise: "'none'"}]}}}]

  - {name: ID, type: str, derivation: SRC.ID}
  - {name: VALUE, type: str}
rows: [{id: groups, dataset: SRC, group_by: [SRC.ID, SRC.V, SRC.TEXT], derivations: {VALUE: {case: [{when: 'SRC.V > 0', then: {str_extract: {source: SRC.TEXT, pattern: 'prefix:([A-Z]+)$', group: 1}}}, {otherwise: "'none'"}]}}}]

      - range: {min: 0.0, max: 1.5}
rows: [{id: records, dataset: SRC, derivations: {VALUE: {case: [{when: 'SRC.V > 0', then: 1}, {otherwise: 0}]}}}]
verifications: [{assert: {require: 'VALUE >= 0'}}]

      - range: {min: 0.0, max: 1.5}
rows: [{id: groups, dataset: SRC, group_by: [SRC.ID, SRC.V], derivations: {VALUE: {case: [{when: 'SRC.V > 0', then: 1}, {otherwise: 0}]}}}]
verifications: [{assert: {require: 'VALUE >= 0'}}]

      - range: {min: 0.0, max: 1.5}
rows: [{id: records, dataset: SRC, derivations: {VALUE: {case: [{when: 'SRC.V > 0', then: 1}, {otherwise: 0}]}}}]
verifications: [{assert: {require: 'VALUE ='}}]

      - range: {min: 0.0, max: 1.5}
rows: [{id: groups, dataset: SRC, group_by: [SRC.ID, SRC.V], derivations: {VALUE: {case: [{when: 'SRC.V > 0', then: 1}, {otherwise: 0}]}}}]
verifications: [{assert: {require: 'VALUE ='}}]

      - range: {min: 0.0, max: 1.5}
rows: [{id: records, dataset: SRC, derivations: {VALUE: {case: [{when: 'SRC.V > 0', then: 1}, {otherwise: 0}]}}}]
verifications: [{assert: {require: 7}}]

      - range: {min: 0.0, max: 1.5}
rows: [{id: groups, dataset: SRC, group_by: [SRC.ID, SRC.V], derivations: {VALUE: {case: [{when: 'SRC.V > 0', then: 1}, {otherwise: 0}]}}}]
verifications: [{assert: {require: 7}}]

